def expand(a, h, w):
    rows = []
    for i in range(3):
        r = []
        for j in range(3):
            r.extend([a[i][j]]*w[j])
        for _ in range(h[i]):
            rows.append(r[:])
    return rows

def blockize(o):
    # infer h,w from output
    hs, ws = [], []
    prev = None
    for r in o:
        if prev is not None and r == prev: hs[-1]+=1
        else: hs.append(1)
        prev = r
    prev=None
    for c in zip(*o):
        if prev is not None and list(c)==prev: ws[-1]+=1
        else: ws.append(1)
        prev=list(c)
    return hs, ws

